JdbcTemplateSpring对JDBC进行封装，使用JdbcTemplate可以非常方便的进行数据库操作。
使用在SpringBoot下配置之后，DataSource和JdbcTemplate通过@Autowired可以直接操作数据库。
@AutowiredJdbcTemplate template;

代码示例@RestControllerpublic class JDBCController &#123;    @Autowired    JdbcTemplate template;    //查询数据库所有信息 并显示在网页上    //没有实体类 数据库中的数据如何获取    @RequestMapping(&quot;/user/list&quot;)    public List&lt;Map&lt;String,Object&gt;&gt; userList()&#123;        String sql = &quot;select * from user&quot;;        List&lt;Map&lt;String, Object&gt;&gt; list_maps = template.queryForList(sql);        return list_maps;    &#125;    @GetMapping(&quot;/user/add&quot;)    public String addUser(User user)&#123;        //username=ZhangSan&amp;password=zs1234556&amp;nickname=zs&amp;regdate=2022-02-22        System.out.println(user);        String sql = String.format(&quot;insert into `springbootstudy`.`user`(`username`,`password`,`nickname`,`regdate`) values(&#x27;%s&#x27;,&#x27;%s&#x27;,&#x27;%s&#x27;,&#x27;%s&#x27;)&quot;,                user.getUsername(),                user.getPassword(),                user.getNickname(),                new SimpleDateFormat(&quot;yyyy-MM-dd&quot;).format(user.getRegdate())        );        System.out.println(sql);        try &#123;            return String.valueOf(template.update(sql));        &#125;catch (Exception e)&#123;            return sql;        &#125;    &#125;    @GetMapping(&quot;/user/delete/&#123;id&#125;&quot;)    public String deleteUser(@PathVariable(&quot;id&quot;) Integer id)&#123;        //id=1        String sql = &quot;delete from user where id=?&quot;;        return String.valueOf(template.update(sql,id));    &#125;    @GetMapping(&quot;/user/update&quot;)    public String updateUser(User user)&#123;        //username=ZhangSan&amp;password=zs1234556&amp;nickname=zs&amp;regdate=2022-02-22        System.out.println(user);        String sql = &quot;update user set username=?,password=?,nickname=? where id=?&quot;;        //封装        Object[] objects = &#123;                user.getUsername(),                user.getPassword(),                user.getNickname(),                user.getId()        &#125;;        return String.valueOf(template.update(sql,objects));    &#125;&#125;

