Shirohttps://shiro.apache.org/
介绍
Shiro与SpringSecurity类似；
Apache Shiro是一个Java的安全（权限）框架；
Shiro可以完成认证、授权、加密、会话管理、Web集成、缓存等。


subject：应用代码直接交互的对象Subject，即Shiro的对外API核心就是Subject，Subject代表了当前的用户。
SecurityManager：安全管理器，管理所有的Subject，负责与Shiro其他组件交互。
Realm：Shiro从Realm获取安全数据（用户，角色，权限）。SecurityManager要验证用户身份，需要从Realm获取相应的用户进行比较。
第一个Shiro程序依赖pom.xml&lt;dependencies&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.apache.shiro&lt;/groupId&gt;        &lt;artifactId&gt;shiro-core&lt;/artifactId&gt;        &lt;version&gt;1.9.1&lt;/version&gt;    &lt;/dependency&gt;    &lt;!-- Shiro uses SLF4J for logging.  We&#x27;ll use the &#x27;simple&#x27; binding         in this example app.  See http://www.slf4j.org for more info. --&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.slf4j&lt;/groupId&gt;        &lt;artifactId&gt;slf4j-simple&lt;/artifactId&gt;        &lt;version&gt;1.7.36&lt;/version&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.slf4j&lt;/groupId&gt;        &lt;artifactId&gt;slf4j-api&lt;/artifactId&gt;        &lt;version&gt;1.7.36&lt;/version&gt;    &lt;/dependency&gt;    &lt;dependency&gt;        &lt;groupId&gt;org.slf4j&lt;/groupId&gt;        &lt;artifactId&gt;jcl-over-slf4j&lt;/artifactId&gt;        &lt;version&gt;1.7.21&lt;/version&gt;    &lt;/dependency&gt;&lt;/dependencies&gt;

shiro.ini# =============================================================================# Tutorial INI configuration## Usernames/passwords are based on the classic Mel Brooks&#x27; film &quot;Spaceballs&quot; :)# =============================================================================# -----------------------------------------------------------------------------# Users and their (optional) assigned roles# username = password, role1, role2, ..., roleN# -----------------------------------------------------------------------------[users]root = secret, adminguest = guest, guestlunch = lunch, eaterwater = water, drinker# -----------------------------------------------------------------------------# Roles with assigned permissions# roleName = perm1, perm2, ..., permN# -----------------------------------------------------------------------------[roles]admin = *eater = eat:*drinker = drink:kola:nosugar

主程序import org.apache.shiro.SecurityUtils;import org.apache.shiro.authc.*;import org.apache.shiro.config.IniSecurityManagerFactory;import org.apache.shiro.mgt.SecurityManager;import org.apache.shiro.session.Session;import org.apache.shiro.subject.Subject;import org.apache.shiro.util.Factory;import org.slf4j.Logger;import org.slf4j.LoggerFactory;public class Hello &#123;    private static final transient Logger log = LoggerFactory.getLogger(Hello.class);    public static void main(String[] args) &#123;        log.info(&quot;My First Apache Shiro Application&quot;);        //1. 获得安全管理器Factory        Factory&lt;SecurityManager&gt; factory = new IniSecurityManagerFactory(&quot;classpath:shiro.ini&quot;);        //2. 获得安全管理器实例        SecurityManager securityManager = factory.getInstance();        //3. 设置安全管理器        SecurityUtils.setSecurityManager(securityManager);        Subject currentUser = SecurityUtils.getSubject();//获取当前用户        //若当前用户没有登录        if (!currentUser.isAuthenticated())&#123;            UsernamePasswordToken token = new UsernamePasswordToken(&quot;root&quot;,&quot;secret&quot;);            token.setRememberMe(true);            try &#123;                currentUser.login(token);            &#125; catch (UnknownAccountException e) &#123;                log.info(&quot;未知用户名&quot;);            &#125;catch (IncorrectCredentialsException ice)&#123;                log.info(&quot;错误的密码&quot;);            &#125;catch (LockedAccountException lae)&#123;                log.info(&quot;锁定的账户&quot;);            &#125;        &#125;        Session session = currentUser.getSession();//获取当前用户的Session        session.setAttribute(&quot;key&quot;,&quot;value&quot;);//设置key和value        String value = (String) session.getAttribute(&quot;key&quot;);//获取key-value        if (&quot;value&quot;.equals(value))&#123;            log.info(&quot;正确：&quot;+value);        &#125;        log.info(&quot;当前用户名：&quot;+currentUser.getPrincipal());//获得当前用户名        //当前用户是否拥有角色        if (currentUser.hasRole(&quot;admin&quot;))&#123;            log.info(&quot;管理员？&quot;);        &#125;else &#123;            log.info(&quot;不是管理员&quot;);        &#125;        //测试单权限        if (currentUser.isPermitted(&quot;eat:Obsidian&quot;))&#123;            log.info(&quot;请不要饮食过度&quot;);        &#125;else &#123;            log.info(&quot;你不能吃饭。&quot;);        &#125;        //权限组        if (currentUser.isPermitted(&quot;drink:SnowGreen&quot;))&#123;            log.info(&quot;请不要过度饮雪&quot;);        &#125;else&#123;            log.info(&quot;你不能喝格林雪&quot;);        &#125;    &#125;&#125;

