Fanout生产者示例
使用RabbitMQConfiguration初始化Exchange、Queue以及进行队列交换机绑定；
@Configurationpublic class RabbitMQConfiguration &#123;    //声明注册fanout模式的交换机    @Bean    public FanoutExchange fanoutExchange()&#123;        return new FanoutExchange(&quot;fanoutExchange&quot;,true,false);    &#125;    //声明队列：save, sms, email, notice    @Bean    public Queue saveQueue()&#123;        return new Queue(&quot;save.fanout.queue&quot;,true);    &#125;    @Bean    public Queue smsQueue()&#123;        return new Queue(&quot;sms.fanout.queue&quot;,true);    &#125;    @Bean    public Queue emailQueue()&#123;        return new Queue(&quot;email.fanout.queue&quot;,true);    &#125;    @Bean    public Queue noticeQueue()&#123;        return new Queue(&quot;notice.fanout.queue&quot;,true);    &#125;    //完成绑定关系（队列和交换机完成绑定关系）    @Bean public Binding saveBinding()&#123;return BindingBuilder.bind(saveQueue()).to(fanoutExchange());&#125;    @Bean public Binding smsBinding()&#123;return BindingBuilder.bind(smsQueue()).to(fanoutExchange());&#125;    @Bean public Binding emailBinding()&#123;return BindingBuilder.bind(emailQueue()).to(fanoutExchange());&#125;    @Bean public Binding noticeBinding()&#123;return BindingBuilder.bind(noticeQueue()).to(fanoutExchange());&#125;&#125;

使用rabbitTemplate进行消息发送
@Servicepublic class OrderService &#123;    @Autowired    private RabbitTemplate rabbitTemplate;    /**     * 模拟用户下单     * @param uid  x     * @param pid x     * @param num x     */    public void makeOrder(String uid,String pid,int num)&#123;        //生成订单        String orderId = UUID.randomUUID().toString();        System.out.println(&quot;生成订单：&quot;+orderId);        //通过MQ发送消息        String exchangeName = &quot;fanoutExchange&quot;;        String routingKey = &quot;&quot;;        // 交换机 ，  路由Key或队列名称，  消息内容        rabbitTemplate.convertAndSend(exchangeName,routingKey,orderId);    &#125;&#125;

